import math


ACTIVATION_X_MAX = 10.0


ACTIVATION_X_MIN = 5.0


AGENT_MASS = 5.0


BACKWARD_FX_THRESHOLD = -34.0


BACKWARD_SPEED_MAX = 100.0


EXIT_X_MIN = 15.0


TIME_STEP = 1.0 / 60.0


def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }


class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}


MEM = Memory()


def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(AGENT_MASS) * abs(gy)


def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)


def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()


def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)
    if state["phase"] == "APPROACH":
        fx = 15.0 if x < 5.0 else 10.0 * (7.0 - x) - 5.0 * vxd
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(vxd) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        fx_cmd = cfg["bfx"] - 1.0
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p
        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        fx, fy = 15.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp
    sandbox.apply_agent_force(fx, fy)

import math

ACTIVATION_X_MAX = 10.0
ACTIVATION_X_MIN = 5.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0

class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(5.0) * abs(gy)

def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
        }

    state = MEM.data["initial_state"]
    pd = sandbox.get_agent_position()
    dt = TIME_STEP

    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt

    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)

    if state["phase"] == "APPROACH":
        # Navigate toward the activation zone
        if x < 5.0:
            fx = 15.0
        else:
            fx = 10.0 * (7.0 - x) - 5.0 * vxd

        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Check if we are in the activation zone and velocity is low enough
        if (ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX) and (abs(vxd) < 1.0):
            state["phase"] = "UNLOCK"
            state["t"] = 0

        sandbox.apply_agent_force(fx, fy)

    elif state["phase"] == "UNLOCK":
        # Apply a strong backward force to unlock
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)

        # Ensure the commanded force is strictly less than -34.0 N
        fx_cmd = BACKWARD_FX_THRESHOLD - 1.0  # -35.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Adjust for speed
        if spd >= BACKWARD_SPEED_MAX * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1

        # Transition to escape after 60 steps
        if state["t"] > 60:
            state["phase"] = "ESCAPE"

        sandbox.apply_agent_force(fx, fy)

    elif state["phase"] == "ESCAPE":
        # Move toward the exit zone
        fx = 15.0
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"

        sandbox.apply_agent_force(fx, fy)

    elif state["phase"] == "HOLD":
        # Hold position after unlocking
        fx, fy = 0.0, _weight_comp(sandbox)
        sandbox.apply_agent_force(fx, fy)

