    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    state = MEM.data.get("initial_state", {
        "phase": "APPROACH",
        "t": 0,
        "lx": None,
        "ly": None,
        "vx": 0.0,
        "vy": 0.0,
    })

    pd = sandbox.get_agent_position()
    x, y = pd[0], pd[1]
    front, up, down = sandbox.get_whisker_readings()
    vx_p, vy_p = sandbox.get_agent_velocity()
    spd = math.hypot(vx_p, vy_p)

    in_activation = ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX

    if state["phase"] == "APPROACH":
        # Check if in blind zone (all whiskers at max range)
        if front == 3.0 and up == 3.0 and down == 3.0:
            # Apply strong forward force to move toward activation zone
            fx = 30.0
        else:
            # Use whiskers to avoid walls
            if front < WHISKER_THRESHOLD:
                fx = -MAX_FORCE
            else:
                fx = 10.0 * (ACTIVATION_X_MIN - x) - 5.0 * vx_p

            # Avoid vertical walls
            if up < WHISKER_THRESHOLD:
                fy = -MAX_FORCE
            elif down < WHISKER_THRESHOLD:
                fy = MAX_FORCE
            else:
                fy = 50.0 * (1.5 - y) - 20.0 * vy_p

        # Transition to unlock phase if in activation zone and low velocity
        if in_activation and abs(vx_p) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0

    elif state["phase"] == "UNLOCK":
        # Apply strong backward force for unlock
        fx = -35.0  # Ensures commanded force < -34.0 N

        # Avoid vertical walls
        if up < WHISKER_THRESHOLD:
            fy = -MAX_FORCE
        elif down < WHISKER_THRESHOLD:
            fy = MAX_FORCE
        else:
            fy = 50.0 * (1.5 - y) - 20.0 * vy_p

        # Check unlock conditions
        if spd < BACKWARD_SPEED_MAX and state["t"] >= 5:
            state["phase"] = "ESCAPE"
            state["t"] = 0

        state["t"] += 1

    elif state["phase"] == "ESCAPE":
        # Move toward exit zone
        if x < EXIT_X_MIN:
            fx = 20.0
        else:
            fx = 10.0 * (EXIT_X_MIN - x) - 5.0 * vx_p

        # Avoid vertical walls
        if up < WHISKER_THRESHOLD:
            fy = -MAX_FORCE
        elif down < WHISKER_THRESHOLD:
            fy = MAX_FORCE
        else:
            fy = 50.0 * (1.5 - y) - 20.0 * vy_p

        # Transition to hold phase if in exit zone
        if x >= EXIT_X_MIN:
            state["phase"] = "HOLD"
            state["t"] = 0

    elif state["phase"] == "HOLD":
        # Maintain position in exit zone
        fx = 0.0
        fy = 50.0 * (1.5 - y) - 20.0 * vy_p

        # Ensure hold phase lasts 5 steps
        state["t"] += 1
        if state["t"] >= 5:
            state["phase"] = "DONE"

    # Update state
    state["vx"] = vx_p
    state["vy"] = vy_p
    state["lx"], state["ly"] = x, y
    MEM.data["initial_state"] = state

    sandbox.apply_agent_force(fx, fy)
